Q: How to get all the messages from kafka topic and count them using java? A: <p>Here is your example.</p>

<p>The most important here is Kafka consumer configuration properties:</p>

<p>Will start from the beginning of the queue.  </p>

<pre><code>props.put("auto.offset.reset", "smallest");  
</code></pre>

<p>Won't store offsets for this consumer.</p>

<pre><code>props.put("auto.commit.enable", "false");
</code></pre>

<p>Will wait 5 sec for messages if no more messages available will give up.</p>

<pre><code>props.put("consumer.timeout.ms", "5000");
</code></pre>

<p>The whole example:</p>

<pre><code>package com.xxx.yyy.zzz;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Properties;

import kafka.consumer.Consumer;
import kafka.consumer.ConsumerConfig;
import kafka.consumer.ConsumerTimeoutException;
import kafka.consumer.KafkaStream;
import kafka.javaapi.consumer.ConsumerConnector;

public class KafkaConsumer {
    private final ConsumerConnector consumer;
    private final String topic;
    private int count = 0;

    public KafkaConsumer(final String zookeeper, final String groupId, final String topic) {
        this.consumer = Consumer.createJavaConsumerConnector(createConsumerConfig(zookeeper, groupId));
        this.topic = topic;
    }

    // Initialize connection properties to Kafka and Zookeeper
    private static ConsumerConfig createConsumerConfig(final String zookeeper, final String groupId) {
        Properties props = new Properties();
        props.put("zookeeper.connect", zookeeper);
        props.put("group.id", groupId);
        props.put("zookeeper.session.timeout.ms", "2000");
        props.put("zookeeper.sync.time.ms", "250");
        props.put("auto.commit.interval.ms", "1000");
        props.put("auto.offset.reset", "smallest");
        props.put("auto.commit.enable", "false");
        props.put("consumer.timeout.ms", "5000");

        return new ConsumerConfig(props);
    }

    private void getData() {
        List&lt;byte[]&gt; msgs = new ArrayList();
        Map&lt;String, Integer&gt; topicMap = new HashMap&lt;&gt;();

        // Define single thread for topic
        topicMap.put(topic, 1);
        try {
            Map&lt;String, List&lt;KafkaStream&lt;byte[], byte[]&gt;&gt;&gt; listMap = consumer.createMessageStreams(topicMap);
            List&lt;KafkaStream&lt;byte[], byte[]&gt;&gt; kafkaStreams = listMap.get(topic);

            // Collect the messages.
            kafkaStreams.forEach(ks -&gt; ks.forEach(mam -&gt; msgs.add(mam.message())));

        } catch (ConsumerTimeoutException exception) {
            // There no more messages available -&gt; so, we are done.

            // Now print all your messages
            msgs.forEach(System.out::println);

            // count them
            count = msgs.size();
        } finally {
            if (consumer != null) {
                consumer.shutdown();
            }
        }
    }
}
</code></pre>
